/* 【R50】题库分片合并完成后刷新行测首屏。
   背景：首屏 examInit 用的是合并前的 EXAM_BANK（内置题），分片是异步 fetch 进来的；
   合并后只调 renderExamQuestion() 不会重算 examFilteredBank，
   于是「第 x / N 题」的 N 一直停在旧值，必须点一次分类标签才对。
   这里按当前筛选态重算列表并保留当前题序，再重渲染 + 刷新模块统计。
   任何 DOM 缺失（非行测页）都静默跳过，不影响其他页面。 */
function xtRefreshExamBankUI() {
  try {
    var active = document.querySelector('#ecTypeFilter .type-filter.active');
    var type = (active && active.dataset) ? active.dataset.type : '';
    if (type && type !== '全部') {
      examFilteredBank = EXAM_BANK.filter(function (q) { return q.type === type; });
    } else if (typeof examMode !== 'undefined' && examMode === 'review' && typeof getReviewQuestions === 'function') {
      examModeList = getReviewQuestions();
      examFilteredBank = examModeList;
    } else if (typeof getNewQuestions === 'function') {
      examModeList = getNewQuestions();
      examFilteredBank = examModeList;
    } else {
      examFilteredBank = [...EXAM_BANK];
    }
    if (typeof examCurrentIndex !== 'undefined' && examCurrentIndex >= examFilteredBank.length) examCurrentIndex = 0;
    if (typeof renderExamQuestion === 'function') renderExamQuestion();
    if (typeof updateModuleStats === 'function') updateModuleStats();
  } catch (e) { /* 非行测页 / DOM 缺失：静默 */ }
}
window.xtRefreshExamBankUI = xtRefreshExamBankUI;

// 加载单个题库 JSON 分片。allowOverride=true → 覆盖层语义（同 id 覆盖内置）；
// 省略 / false → 增量分片语义（同 id 跳过、新 id 追加）。任何情况都不落盘（不调 saveData）。
function loadExamBankShard(url, allowOverride) {
  // 【R35 遗留】统一走 fetchJSONAnywhere（fetch 优先、XHR 兜底，file:// 下可用）；
  // 失败 → console.warn（带 url 与错误信息）+ 一次性 toast（同名只提示一次），回退内置题库。
  // 任何情况都不落盘（不调 saveData）。返回 Promise<实际变更条数>。
  return fetchJSONAnywhere(url)
    .then(function (j) {
      if (!j || !Array.isArray(j.questions)) {
        console.warn('[exam] 题库分片结构无效，已跳过：', url);
        notifyDataLoadFailed('题库扩展', url, '⚠️ 题库扩展加载失败，当前仅显示内置题目');
        return 0;
      }
      var changed = mergeExamBankQuestions(j.questions, !!allowOverride);
      // 【R50】有新增就重算列表 + 重渲染（原来只 renderExamQuestion，题数不刷新）
      if (changed > 0) xtRefreshExamBankUI();
      return changed;
    })
    .catch(function (err) {
      console.warn('[exam] 题库分片加载失败，回退内置：', url, err && err.message ? err.message : err);
      notifyDataLoadFailed('题库扩展', url, '⚠️ 题库扩展加载失败，当前仅显示内置题目');
      return 0;
    });
}

// 统一入口：① 覆盖层（同 id 覆盖内置）→ ② 增量分片索引（只 push）。
function loadExamBankExt() {
  // ① 覆盖层：按显式路径立即加载，索引不可用（file:// / 离线）时也能覆盖内置，保证兜底与线上一致
  loadExamBankShard(EXAM_BANK_LEGACY, true);
  // ② 增量分片：先拉索引，再按 shards[].file 逐片加载 —— 加题只改索引，代码零改动
  // 【R35 遗留】索引同样统一走 fetchJSONAnywhere：失败 → console.warn（带 url 与错误信息）
  // + 一次性 toast（同名只提示一次），回退内置题库 + 覆盖层。
  fetchJSONAnywhere(EXAM_BANK_EXT_INDEX).then(function (idx) {
    if (!idx) {
      console.warn('[exam] 题库分片索引不可用，回退内置 + 覆盖层：', EXAM_BANK_EXT_INDEX);
      notifyDataLoadFailed('题库扩展', EXAM_BANK_EXT_INDEX, '⚠️ 题库扩展加载失败，当前仅显示内置题目');
      return;
    }
    var files = [];
    if (Array.isArray(idx.shards)) {
      idx.shards.forEach(function (s) {
        var f = (s && typeof s === 'object') ? s.file : s; // 兼容 shards 项直接写成文件名的旧格式
        if (typeof f === 'string' && f) files.push(f);
      });
    }
    // 索引若另行声明 legacy（与 EXAM_BANK_LEGACY 相同则跳过，避免重复覆盖）
    // 比较时剥掉查询串（?v=），否则单边带版本号会导致字符串不等、legacy 被加载两遍。
    if (idx.legacy) {
      var lg = (typeof idx.legacy === 'object') ? idx.legacy.file : idx.legacy;
      var lgPath = String(lg).split('?')[0];
      var legacyPath = String(EXAM_BANK_LEGACY).split('?')[0];
      if (typeof lg === 'string' && lg && lgPath !== legacyPath) files.push(lg);
    }
    // 【R50】所有分片落地后再统一刷新一次，保证「第 x / N 题」的 N 是全量题库
    Promise.all(files.map(function (f) { return loadExamBankShard(f); }))
      .then(function () { xtRefreshExamBankUI(); })
      .catch(function () { xtRefreshExamBankUI(); });
  }).catch(function (err) {
    console.warn('[exam] 题库分片索引加载失败，回退内置 + 覆盖层：', EXAM_BANK_EXT_INDEX, err && err.message ? err.message : err);
    notifyDataLoadFailed('题库扩展', EXAM_BANK_EXT_INDEX, '⚠️ 题库扩展加载失败，当前仅显示内置题目');
  });
}

// ========== T06（批次三 R3-1）+ 批次五：词库增量分片加载合并 ==========
// 分片体系：assets/data/vocab-cet4-ext-index.json 声明各分片（按首字母区间 a-c … v-z）。
// 入口 loadVocabExt() 读索引 → Promise.all 并发拉取所有分片 → 同一套 mergeVocabWords() 合并。
// 加词只改「对应分片 + 该片 count」，代码零改动。
// 键=word；已存在词条不覆盖（vocabLearned 按 word 匹配，学习标记不丢失）。全程绝不调用 saveData()。
const VOCAB_EXT_INDEX = 'assets/data/vocab-cet4-ext-index.json?v=20260914f';

// 统一合并：把一批增量词条并入内置 CET_VOCAB；已存在词条（含内置 466）不覆盖。
// 返回实际追加条数。绝不落盘（不调 saveData）。
function mergeVocabWords(words) {
  if (!Array.isArray(words) || typeof CET_VOCAB === 'undefined' || !CET_VOCAB) return 0;
  var seen = {};
  CET_VOCAB.forEach(function (w) { if (w && w.word) seen[w.word] = 1; });
  var added = 0;
  words.forEach(function (nw) {
    if (!nw || !nw.word || seen[nw.word]) return; // 已存在词条不覆盖
    seen[nw.word] = 1; CET_VOCAB.push(nw); added++;
  });
  return added;
}

// 合并后若确有新增，触发词表重渲染：
// ① 派发 window 级 'vocab-merged' 事件（detail.added=新增条数），供四级词汇页等监听方重渲染；
// ② 兼容旧入口（词库侧若存在 renderVocabList / renderCetVocab 则直接调用；不存在则跳过）。
function afterVocabMerge(added) {
  if (added > 0) {
    try { window.dispatchEvent(new CustomEvent('vocab-merged', { detail: { added: added } })); } catch (e) { /* 老环境无 CustomEvent：静默 */ }
    if (typeof renderVocabList === 'function') { try { renderVocabList(); } catch (e) {} }
    else if (typeof renderCetVocab === 'function') { try { renderCetVocab(); } catch (e) {} }
  }
}

// R35：通用 JSON 拉取——先标准 fetch（resp.ok 检查），任何异常/失败回退 XHR
// （Promise 包装 XMLHttpRequest，同步式 GET）；file:// 下 fetch 会被拒而 XHR 可用，
// 本地打开也能加载全量词库。两级都失败才 reject。
// 判定约定：XHR 成功 = status 2xx；老 WebView file:// 下成功响应可能返回 status 0，
// 此时以「status===0 且 responseText 非空」作为补充成功判定（仍以 2xx 为主）。
function fetchJSONAnywhere(url) {
  return new Promise(function (resolve, reject) {
    function tryXhr() {
      try {
        var xhr = new XMLHttpRequest();
        xhr.open('GET', url, true);
        xhr.onreadystatechange = function () {
          if (xhr.readyState !== 4) return;
          var ok = (xhr.status >= 200 && xhr.status < 300) || (xhr.status === 0 && !!xhr.responseText);
          if (ok) {
            try { resolve(JSON.parse(xhr.responseText)); }
            catch (pe) { reject(pe); }
          } else {
            reject(new Error('XHR ' + xhr.status + ' ' + url));
          }
        };
        xhr.onerror = function () { reject(new Error('XHR network error ' + url)); };
        xhr.send(null);
      } catch (xe) { reject(xe); }
    }
    var p;
    try {
      p = fetch(url).then(function (resp) {
        if (!resp.ok) throw new Error('HTTP ' + resp.status + ' ' + url);
        return resp.json();
      });
    } catch (fe) {
      tryXhr(); return; // fetch 同步抛出（老环境无 fetch）→ 直接走 XHR
    }
    p.then(resolve, function () { tryXhr(); }); // fetch 异步失败（含 file:// 拒绝）→ 回退 XHR
  });
}

// R35：词库扩展全量失败时的一次性提示（防重入标记，只提示一次）
// 【R35 遗留】数据加载失败统一提示：同名只提示一次（防重复弹窗刷屏）。
// 词库 / 题库等所有 file:// 静态 JSON 加载链共用这一套。
var _dataLoadFailedFlags = {};
function notifyDataLoadFailed(name, detail, msg) {
  if (_dataLoadFailedFlags[name]) return;
  _dataLoadFailedFlags[name] = true;
  try { console.warn('[data] ' + name + ' 加载失败，回退内置数据：', detail || ''); } catch (e) { /* 静默 */ }
  try { showToast(msg || ('⚠️ ' + name + ' 加载失败，当前仅显示内置内容')); } catch (e) { /* 静默 */ }
}

// R35：词库扩展专用入口（保留原提示文案，内部转调通用实现）
function notifyVocabExtFailed() {
  notifyDataLoadFailed('词库扩展', VOCAB_EXT_INDEX, '⚠️ 词库扩展加载失败，当前仅显示内置词表');
}

// 增量分片加载：读索引 → 并发拉取所有分片 → 合并。
// R35 重构：索引与分片统一走 fetchJSONAnywhere（fetch 失败回退 XHR，file:// 可用）；
// 容错：单片失败 → 跳过该片、console.warn（带 url 与错误信息），其余片照常合并；
//       索引失败 / 无有效分片 / 全部分片失败（added===0）→ console.warn + 一次性
//       showToast 提示回退内置 466 词。范围控制：本批只动词库链，exam/listening 链不改。
function loadVocabExt() {
  fetchJSONAnywhere(VOCAB_EXT_INDEX).then(function (idx) {
    if (!idx || !Array.isArray(idx.shards) || !idx.shards.length) {
      console.warn('[vocab] 词库扩展索引不可用，回退内置 466：', VOCAB_EXT_INDEX);
      notifyVocabExtFailed();
      return null;
    }
    var files = [];
    idx.shards.forEach(function (s) {
      var f = (s && typeof s === 'object') ? s.file : s; // 兼容 shards 项直接写成文件名的旧格式
      if (typeof f === 'string' && f) files.push(f);
    });
    if (!files.length) {
      console.warn('[vocab] 词库扩展索引无有效分片：', VOCAB_EXT_INDEX);
      notifyVocabExtFailed();
      return null;
    }
    return Promise.all(files.map(function (f) {
      return fetchJSONAnywhere(f)
        .then(function (j) {
          return (j && Array.isArray(j.words)) ? { file: f, words: j.words } : { file: f, failed: true };
        })
        .catch(function (err) {
          console.warn('[vocab] 分片加载失败，已跳过：', f, err && err.message ? err.message : err);
          return { file: f, failed: true };
        });
    })).then(function (parts) {
      var merged = [];
      var failed = [];
      parts.forEach(function (p) {
        if (p && !p.failed && Array.isArray(p.words)) merged = merged.concat(p.words);
        else failed.push(p ? p.file : '?');
      });
      if (failed.length) {
        try { console.warn('[vocab] 分片加载失败清单：' + failed.join(', ')); } catch (e) {}
      }
      var added = mergeVocabWords(merged);
      if (added === 0) notifyVocabExtFailed(); // 一片都没成功合并 → 一次性提示
      afterVocabMerge(added);
    });
  }).catch(function (err) {
    console.warn('[vocab] 词库扩展索引加载失败，回退内置 466：', VOCAB_EXT_INDEX, err && err.message ? err.message : err);
    notifyVocabExtFailed();
  });
}

// 启动合并（file:// 失败自动回退内置兜底）
try { loadVocabExt(); loadExamBankExt(); } catch (e) { /* 静默 */ }

